WITH scored AS (SELECT id, temp_c, humidity, pressure, status_bits, firmware, MAX(pressure) OVER w_grp AS running_max_pressure, SUM(pressure) OVER w_grp AS running_sum_pressure, COUNT(pressure) OVER w_grp AS running_count_pressure FROM device_readings WINDOW w_grp AS (PARTITION BY device_code ORDER BY status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), scored_device_readings AS (SELECT *, AVG(temp_c) OVER w_ordered AS temp_c_avg_6_prior, ROW_NUMBER() OVER (ORDER BY running_max_pressure, id) AS seq_no, ROW_NUMBER() OVER (ORDER BY status_bits, id) AS event_seq FROM scored WINDOW w_ordered AS (ORDER BY running_sum_pressure, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING)), base AS (SELECT id, temp_c, humidity, pressure, firmware, running_max_pressure, running_sum_pressure, seq_no, event_seq, CAST(pressure AS INT) AS pressure_int FROM scored_device_readings WHERE temp_c BETWEEN 33 AND 36), metrics AS (SELECT id, humidity, pressure, running_max_pressure, running_sum_pressure, seq_no, event_seq, pressure_int, LAG(humidity, 2) OVER w_part AS prev_humidity, LEAD(temp_c, 1) OVER w_part AS next_temp_c FROM base WINDOW w_part AS (ORDER BY seq_no, id)), matched_keys AS (SELECT id FROM metrics EXCEPT SELECT id FROM device_readings WHERE humidity <= 74), reconciled AS (SELECT s.* FROM metrics s INNER JOIN matched_keys k ON s.id = k.id) SELECT CASE WHEN event_seq >= 9 THEN 'LARGE' ELSE 'SMALL' END AS event_seq_tier, seq_no, MAX(running_sum_pressure) AS max_running_sum_pressure, APPROX_PERCENTILE(pressure, 0.9) AS pressure_p90, COUNT(*) AS num_rows, RANK() OVER (PARTITION BY CASE WHEN event_seq >= 9 THEN 'LARGE' ELSE 'SMALL' END ORDER BY APPROX_PERCENTILE(pressure, 0.9) DESC) AS pressure_p90_rank FROM reconciled GROUP BY CASE WHEN event_seq >= 9 THEN 'LARGE' ELSE 'SMALL' END, seq_no HAVING APPROX_PERCENTILE(pressure, 0.9) >= 0
